<script setup>
import { reactive, ref } from 'vue'
import { useEvents } from '@/composables/useEvents'
const emit = defineEmits(['success','cancel'])
const { createEvent } = useEvents()
const form = reactive({ title:'',cat:'Workshop',date:'',loc:'',quota:100,price:'Free',desc:'' })
const errorMessage = ref('')
function handleSubmit() {
  if (!form.title.trim() || !form.date || !form.loc.trim() || !form.desc.trim()) { errorMessage.value='Please fill in all required fields before publishing the event!'; return }
  createEvent({ ...form, date: new Date(form.date).toLocaleString('en-US',{dateStyle:'medium',timeStyle:'short'}) })
  Object.assign(form,{title:'',cat:'Workshop',date:'',loc:'',quota:100,price:'Free',desc:''})
  errorMessage.value='';emit('success')
}
</script><template><div class="event-form"><h3>Create New Event Form</h3><p>Information entered here will be instantly published to the Gatherly public catalog.</p><div v-if="errorMessage" class="alert-error">{{ errorMessage }}</div><form @submit.prevent="handleSubmit" novalidate><div class="form-group"><label>Event Title <span>*</span><input v-model="form.title" placeholder="e.g. Modern UI/UX Masterclass"/></label></div><div class="form-row"><div class="form-group"><label>Event Category <span>*</span></label><select v-model="form.cat"><option v-for="cat in ['Workshop','Meetup','Competition','Seminar','Conference']" :key="cat">{{ cat }}</option></select></div><div class="form-group"><label>Date & Time <span>*</span></label><input v-model="form.date" type="datetime-local"/></div></div><div class="form-row"><div class="form-group"><label>Venue / Location <span>*</span></label><input v-model="form.loc" placeholder="e.g. Innovation Center, Jakarta"/></div><div class="form-group"><label>Attendee Quota</label><input v-model.number="form.quota" type="number" min="1"/></div></div><div class="form-group"><label>Event Description <span>*</span></label><textarea v-model="form.desc" rows="5" placeholder="Describe the agenda, speakers, and key takeaways..."></textarea></div><div class="form-actions"><button type="button" class="btn-secondary" @click="emit('cancel')">Cancel</button><button type="submit" class="btn-primary">Publish Event Now</button></div></form></div></template>
<style scoped>.event-form{padding:26px;background:#fff;border:1px solid var(--border-color);border-radius:12px;max-width:860px}.event-form>p{color:var(--text-muted);font-size:.9rem}.event-form form{display:flex;flex-direction:column;gap:22px;margin-top:22px}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:20px}.form-group{display:flex;flex-direction:column;gap:8px}.form-group label{font-size:.9rem;font-weight:700}.form-group label span{color:#dc3545}.form-group input,.form-group select,.form-group textarea{font:inherit;padding:12px 14px;border:1px solid var(--border-color);border-radius:8px;width:100%}.form-group input:focus,.form-group select:focus,.form-group textarea:focus{outline:1px solid var(--primary)}.form-actions{display:flex;justify-content:flex-end;gap:12px;padding-top:12px;border-top:1px solid var(--border-color)}.form-actions button{padding:12px 18px;border-radius:8px;font-weight:700;cursor:pointer}.btn-primary{background:var(--primary);color:#fff;border:0}.btn-secondary{background:#fff;color:var(--text-muted);border:1px solid var(--border-color)}.alert-error{color:#b91c1c;background:#fee2e2;padding:12px;border-radius:8px}@media(max-width:768px){.form-row{grid-template-columns:1fr}}</style>
